//! turbo-unicode's frozen Hugging Face profile (analysis/unicode/src/
//! normalize/hf, generated by scripts/hf-unicode-tables) against
//! upstream's own NFC and NFD: every primary composite turbo-unicode
//! composes, and every scalar's decomposition and canonical order.

use tokenizers::tokenizer::NormalizedString;
use turbo_unicode::hf;
use turbo_unicode::normalize::{Form, canonical_decomposition, compose};

fn ours(form: Form, text: &str) -> String {
    hf::aligned(form, text).map(|(c, _)| c).collect()
}

fn upstream(form: Form, text: &str) -> String {
    let mut normalized = NormalizedString::from(text);
    match form {
        Form::Nfc => normalized.nfc(),
        _ => normalized.nfd(),
    };
    normalized.get().to_owned()
}

/// A pair whose first character is itself newer than upstream's tables
/// is never decomposed, so a blacklist from decompositions alone misses
/// it, as it did U+16121 U+1611F.
#[test]
fn frozen_composition_matches_upstream_on_every_primary_composite() {
    let mut pairs = 0;
    for c in (0..=0x10ffffu32).filter_map(char::from_u32) {
        let Some(&[a, b]) = canonical_decomposition(c) else { continue };
        if compose(a, b) != Some(c) {
            continue;
        }
        pairs += 1;
        let text: String = [a, b].into_iter().collect();
        assert_eq!(ours(Form::Nfc, &text), upstream(Form::Nfc, &text), "{a:?} + {b:?} (now {c:?})");
    }
    assert!(pairs > 900, "only {pairs} primary composites");
}

/// Each scalar alone, and between a starter and marks of class 230 and 1,
/// so a combining class that differs reorders differently.
#[test]
fn frozen_decomposition_and_order_match_upstream_on_every_scalar() {
    for c in (0..=0x10ffffu32).filter_map(char::from_u32) {
        for text in [format!("{c}"), format!("a{c}\u{301}"), format!("a{c}\u{334}"), format!("a\u{301}{c}")] {
            assert_eq!(ours(Form::Nfd, &text), upstream(Form::Nfd, &text), "NFD of {text:?}");
        }
    }
}
